import java.nio.file.Paths;

public class FileService {
    private static final Path BASE_DIR = Paths.get("/tmp/upload");

    public String readFileContent(String filePath) throws IOException {
        // 验证基础目录是否存在
        if (!Files.exists(BASE_DIR)) {
            throw new IOException("Base directory does not exist: " + BASE_DIR);
        }

        // 解析并规范化文件路径
        Path resolvedPath = BASE_DIR.resolve(filePath).normalize();

        // 安全检查：确保路径在基础目录内
        if (!resolvedPath.startsWith(BASE_DIR)) {
            throw new IOException("Invalid file path: " + filePath + " (path traversal attempt)");
        }

        // 检查文件是否存在
        if (!Files.exists(resolvedPath)) {
            throw new IOException("File does not exist: " + resolvedPath);
        }

        // 检查是否是常规文件
        if (!Files.isRegularFile(resolvedPath)) {
            throw new IOException("Path is not a regular file: " + resolvedPath);
        }

        // 读取文件内容
        try {
            byte[] fileBytes = Files.readAllBytes(resolvedPath);
            return new String(fileBytes, StandardCharsets.UTF_8);
        } catch (IOException e) {
            throw new IOException("Failed to read file: " + resolvedPath, e);
        }
    }
}
